#include <zephyr/ztest.h>
#include <zephyr/kernel.h>
#include <stdlib.h> /* For malloc and free */
#include <string.h> /* For memset */

#define TEST_SMALL_SIZE 10
#define TEST_MEDIUM_SIZE 128
#define TEST_LARGE_SIZE 1024

/**
 * @brief Test basic malloc/free functionality.
 *
 * This test allocates a buffer, writes to it, and then frees it.
 * It also checks for common pitfalls like freeing NULL and zero-size allocations.
 */
ZTEST(test_malloc, test_basic_alloc_free)
{
    char *buf;
    int i;

    /* Test small allocation */
    buf = (char *)malloc(TEST_SMALL_SIZE);
    zassert_not_null(buf, "malloc failed to allocate %d bytes", TEST_SMALL_SIZE);

    /* Initialize the buffer with known values (correct bounds) */
    for (i = 0; i < TEST_SMALL_SIZE; i++) {
        buf[i] = (char)i;
    }

    /* Verify the written values */
    for (i = 0; i < TEST_SMALL_SIZE; i++) {
        zassert_equal(buf[i], (char)i, "Buffer content mismatch at index %d", i);
    }

    /* Free the allocated buffer */
    free(buf);

    /* Test freeing NULL pointer (should be safe) */
    free(NULL);

    /* Test zero-size allocation: should return NULL or a valid pointer that can be freed */
    buf = (char *)malloc(0);
    /* Depending on libc implementation, malloc(0) can return NULL or a non-NULL pointer
     * that can be safely freed. We assert it's not a crash and can be freed.
     */
    if (buf != NULL) {
        free(buf);
    }
}

/**
 * @brief Test multiple allocations and frees of different sizes.
 */
ZTEST(test_malloc, test_multiple_alloc_free)
{
    char *ptrs[5];
    size_t sizes[] = {TEST_SMALL_SIZE, TEST_MEDIUM_SIZE, TEST_LARGE_SIZE, 32, 64};
    int i;

    /* Allocate multiple blocks */
    for (i = 0; i < ARRAY_SIZE(ptrs); i++) {
        ptrs[i] = (char *)malloc(sizes[i]);
        zassert_not_null(ptrs[i], "malloc failed for size %zu", sizes[i]);
        /* Fill with a pattern to detect corruption */
        memset(ptrs[i], (char)(i + 1), sizes[i]);
    }

    /* Free multiple blocks */
    for (i = 0; i < ARRAY_SIZE(ptrs); i++) {
        free(ptrs[i]);
    }
}

/**
 * @brief Test allocation and freeing of a large block.
 */
ZTEST(test_malloc, test_large_alloc)
{
    char *buf;

    buf = (char *)malloc(TEST_LARGE_SIZE);
    zassert_not_null(buf, "malloc failed to allocate %d bytes", TEST_LARGE_SIZE);
    memset(buf, 0xAA, TEST_LARGE_SIZE);
    free(buf);
}

ZTEST_SUITE(test_malloc, NULL, NULL, NULL, NULL, NULL);
